window.VENOMED_DATA = {"categories": [{"id": "menu-serpents", "menu_id": "Menu serpents", "title": "Serpents de France métropolitaine"}, {"id": "menu-araignees", "menu_id": "Menu araignées", "title": "Araignées de France"}, {"id": "menu-scorpions", "menu_id": "Menu scorpions", "title": "Scorpions de France"}, {"id": "menu-insectes-volants", "menu_id": "Menu insectes volants", "title": "Insecte volant"}, {"id": "menu-animaux-marins", "menu_id": "Menu animaux marins", "title": "Animaux marins"}, {"id": "menu-batraciens", "menu_id": "Menu batraciens", "title": "Batraciens"}, {"id": "menu-autres", "menu_id": "Menu Autres", "title": "Autres"}], "species": [{"id": "coronelle-lisse", "name": "Coronelle lisse", "category": "menu-serpents", "category_title": "Serpents de France métropolitaine", "danger": "Inoffensif", "id_screen": "Coronelle lisse 1", "info_screen": "Coronelle lisse 2", "images": ["ResFile147446076469.webp", "ResFile147446077558.webp", "ResFile147446078577.webp", "ResFile147446079478.webp"], "syndrome": null, "sections": [{"h": "Coronelle lisse\n(Coronella austriaca)", "body": "Ce serpent gris à brun ou roussâtre mesure entre 50 et 70 cm de long. C'est un type de couleuvre diurne qui est actif du printemps à l'automne, et vit principalement dans les landes et les lisières de bois. Il n'est pas venimeux, et se nourrit principalement de lézards qu'il tue par constriction"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nSe référer à un médecin."}, {"h": "Prise en charge médicale", "body": "La coronelle lisse ne dispose pas de venin.\nAntiseptiques +/- VAT +/- ATB"}], "danger_class": "safe", "danger_short": "Inoffensif"}, {"id": "coronelle-girondine", "name": "Coronelle girondine", "category": "menu-serpents", "category_title": "Serpents de France métropolitaine", "danger": "Inoffensif", "id_screen": "Coronelle Girondine 1", "info_screen": "Coronelle girondine 2", "images": ["ResFile147446062198.webp", "ResFile147446063252.webp", "ResFile147446064339.webp", "ResFile147446065264.webp"], "syndrome": null, "sections": [{"h": "Coronelle girondine\n(Coronella girondica)", "body": "La coronelle girondine est un type de couleuvre qui mesure en général moins de 70 cm de long mais peut aller jusqu'à 100 cm.\nElle vit dans les milieux secs, surtout dans les haies et forêts claires. On peut l'observer autour des vieux tas de végétaux et dans les endroits rocheux (tas de pierres, mur de pierres sèches…).\nElle chasse le soir et la nuit par temps chaud. Elle est particulièrement active pendant les nuits tièdes et pluvieuses de printemps"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nSe référer à un médecin."}, {"h": "Prise en charge médicale", "body": "La coronelle girondine ne dispose pas de venin.\nAntiseptiques +/- VAT +/- ATB"}], "danger_class": "safe", "danger_short": "Inoffensif"}, {"id": "couleuvre-a-collier", "name": "Couleuvre à collier", "category": "menu-serpents", "category_title": "Serpents de France métropolitaine", "danger": "Inoffensif", "id_screen": "Couleuvre a collier 1", "info_screen": "Couleuvre a collier 2", "images": ["ResFile147446097474.webp", "ResFile147446098488.webp", "ResFile147446099323.webp", "ResFile147446100342.webp"], "syndrome": null, "sections": [{"h": "Couleuvre à collier\n(Natrix natrix)", "body": "Ce serpent est largement répandu en Europe ainsi qu'en Afrique du Nord et au Moyen-Orient. Il vit généralement non loin des cours et plans d'eau. Sa taille varie de 65 cm à plus de 1,40 m, voire jusqu'à 2 m, les femelles étant plus grandes que les mâles.\nLes couleuvres à collier hibernent et s'accouplent peu après leur réveil en avril ou en mai, voire en juin"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nSe référer à un médecin."}, {"h": "Prise en charge médicale", "body": "La couleuvre à collier ne dispose pas de venin.\nAntiseptiques +/- VAT +/- ATB"}], "danger_class": "safe", "danger_short": "Inoffensif"}, {"id": "couleuvre-a-echelons", "name": "Couleuvre à échelons", "category": "menu-serpents", "category_title": "Serpents de France métropolitaine", "danger": "Inoffensif", "id_screen": "Couleuvre a echelon 1", "info_screen": "Couleuvre a echelon 2", "images": ["ResFile147446102368.webp", "ResFile147446103270.webp", "ResFile14744610426.webp", "ResFile147446105435.webp"], "syndrome": null, "sections": [{"h": "Couleuvre à échelons\n(Zamenis scalaris)", "body": "Ce sont des serpents diurnes des zones ensoleillées, rocailleuses ou broussailleuses, capables de grimper dans les buissons. Ils se nourrissent de petits mammifères et d'oiseaux.\nLa période d'activité est vers avril-mai et la taille moyenne est d'environ 120cm"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nSe référer à un médecin."}, {"h": "Prise en charge médicale", "body": "La couleuvre à échelons ne dispose pas de venin.\nAntiseptiques +/- VAT +/- ATB"}], "danger_class": "safe", "danger_short": "Inoffensif"}, {"id": "couleuvre-de-montpellier", "name": "Couleuvre de Montpellier", "category": "menu-serpents", "category_title": "Serpents de France métropolitaine", "danger": "Potentiellement venimeux\nEnvenimation particulière", "id_screen": "Couleuvre de MTP 1", "info_screen": "Couleuvre de MTP 2", "images": ["ResFile147446014799.webp", "ResFile147446016278.webp", "ResFile147446017442.webp", "ResFile147446018671.webp"], "syndrome": null, "sections": [{"h": "Couleuvre de Montpellier\n(Malpolon monspessulanus)", "body": "C'est un grand serpent qui peut atteindre une taille totale de 2,55 m, bien qu'il ne dépasse qu'exceptionnellement la taille de 2 m, ce qui en fait le serpent le plus grand d'Europe. Le corps est svelte et la tête étroite.\nLa Couleuvre de Montpellier a une coloration allant du brun au verdâtre, avec le ventre jaune uni.\nCette couleuvre se reproduit d'avril à juin."}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nConsulter un centre de soins"}, {"h": "Prise en charge médicale", "body": "La couleuvre de Montpellier est la seule espèce de couleuvre à posséder des crochets et du venin. Néanmoins, ils sont très postérieurs, et n'atteignent que rarement la victime humaine.\n\n- S'il n'existe pas de traces de crochets, traiter comme une simple morsure (antisepsie +/- VAT +/- ATB)\n\n- S'il existe des traces de crochets, il faut considérer la morsure comme potentiellement envenimante, notamment chez l'enfant ou la personne âgée.\nDans ce cas (extrêmement rare), la toxicité est alors neurologique, pouvant aller jusqu'à la paralysie, et il n'existe aucun traitement spécifique.\nUne surveillance hospitalière s'impose, les symptômes étant habituellement régressifs sous quelques jours."}], "danger_class": "moderate", "danger_short": "Potentiellement venimeux"}, {"id": "couleuvre-d-esculape", "name": "Couleuvre d'Esculape", "category": "menu-serpents", "category_title": "Serpents de France métropolitaine", "danger": "Inoffensif", "id_screen": "Couleuvre esculape 1", "info_screen": "couleuvre esculape 2", "images": ["ResFile147446042999.webp", "ResFile14744604404.webp", "ResFile147446045141.webp", "ResFile147446046046.webp"], "syndrome": null, "sections": [{"h": "Couleuvre d'Esculape\n(Zamenis longissimus)", "body": "La couleuvre d'Esculape fréquente les milieux clairs et ensoleillés mais fuit l'extrême chaleur. Elle se rencontre dans les forêts ensoleillées, les lieux arides ensoleillés, les broussailles, les bords des champs et les vieux murs. Elle vit au sol mais c'est un excellent grimpeur que l'on peut rencontrer posté dans les arbres et arbustes de 15 à 30 m.\nLes accouplements ont lieu à la sortie de l'hivernation, en avril-mai\nLa couleuvre d'Esculape est un serpent d'environ 110 cm à 160 cm de long (rarement 200 cm) au corps long et mince"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nSe référer à un médecin."}, {"h": "Prise en charge médicale", "body": "La couleuvre d'Esculape ne dispose pas de venin.\nAntiseptiques +/- VAT +/- ATB"}], "danger_class": "safe", "danger_short": "Inoffensif"}, {"id": "couleuvre-verte-et-jaune", "name": "Couleuvre verte et jaune", "category": "menu-serpents", "category_title": "Serpents de France métropolitaine", "danger": "Inoffensif", "id_screen": "Couleuvre verte et jaune 1", "info_screen": "couleuvre verte et jaune 2", "images": ["ResFile147446070946.webp", "ResFile147446071987.webp", "ResFile147446074283.webp", "ResFile147446072940.webp"], "syndrome": null, "sections": [{"h": "Couleuvre verte et jaune\n(Hierophis viridiflavus)", "body": "Hierophis viridiflavus mesure entre 100 et 160 cm, voire exceptionnellement jusqu'à 173 cm.\nCette espèce est diurne et ovipare. Active le jour, elle est très rapide et très agile.\n\nElle fréquente les terrains rocheux, secs et bien ensoleillés, exceptionnellement les milieux un peu plus humides comme les prairies et les bords de rivières. On peut la rencontrer près des habitations.\nElle hiverne d'octobre à avril, dans les fissures des rochers, les terriers de mammifères et pond fin juin."}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nSe référer à un médecin."}, {"h": "Prise en charge médicale", "body": "La couleuvre verte et jaune ne dispose pas de venin.\nAntiseptiques +/- VAT +/- ATB"}], "danger_class": "safe", "danger_short": "Inoffensif"}, {"id": "couleuvre-viperine", "name": "Couleuvre vipérine", "category": "menu-serpents", "category_title": "Serpents de France métropolitaine", "danger": "Inoffensif", "id_screen": "Couleuvre vipérine 1", "info_screen": "Couleuvre vipérine 2", "images": ["ResFile14744599264.webp", "ResFile147445994378.webp", "ResFile14744599554.webp", "ResFile147445998287.webp"], "syndrome": null, "sections": [{"h": "Couleuvre vipérine\n(Natrix Maura)", "body": "Natrix maura est un serpent aquatique, vivant dans des milieux humides de zones chaudes. Elle passe toute sa période d'activité, d'avril à octobre, dans des points d'eau (mares, lacs ou cours d'eau n'ayant pas beaucoup de courant)"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nSe référer à un médecin."}, {"h": "Prise en charge médicale", "body": "La couleuvre vipérine ne dispose pas de venin.\nAntiseptiques +/- VAT +/- ATB"}], "danger_class": "safe", "danger_short": "Inoffensif"}, {"id": "vipere-aspic", "name": "Vipère aspic", "category": "menu-serpents", "category_title": "Serpents de France métropolitaine", "danger": "Venimeux\nSyndrome vipérin", "id_screen": "Vipere Aspic 1", "info_screen": "Vipère aspic 2", "images": ["ResFile147446000981.webp", "ResFile147446002258.webp", "ResFile147446003450.webp", "ResFile147446006686.webp"], "syndrome": "syndrome-viperin", "sections": [{"h": "Vipère Aspic\n(Vipera Aspis)", "body": "La période active se situe entre février et novembre.\nElle est commune dans les terrains accidentés mais rare dans les plaines cultivées. Elle est souvent présente dans les milieux secs, tels que les coteaux rocheux embroussaillés ou les bois ouverts et leurs lisières, les murs de pierres sèches. Elle vit également dans les milieux humides, en particulier en hautes montagnes, où on la trouve fréquemment au bord des torrents ou des étangs."}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nSe rendre au centre de soins le plus proche.\nNe pas garroter."}, {"h": "Prise en charge médicale", "body": "La vipère aspic est un serpent venimeux, dont l'envenimation peut être grave."}], "danger_class": "danger", "danger_short": "Venimeux"}, {"id": "vipere-d-orsini", "name": "Vipère d'Orsini", "category": "menu-serpents", "category_title": "Serpents de France métropolitaine", "danger": "Potentiellement venimeux\nSyndrome vipérin", "id_screen": "Vipère Orsini 1", "info_screen": "Vipère Orsini 2", "images": ["ResFile1474460251100.webp", "ResFile147446026216.webp", "ResFile147446027964.webp"], "syndrome": "syndrome-viperin", "sections": [{"h": "Vipère d'Orsini\n(Vipera ursinii)", "body": "Elle vit le jour (diurne), elle est calme et peu agressive mais elle se défend lorsqu'elle est inquiétée ou lorsqu'on la touche. La toxicité de son venin varie selon les régions, mais est trois à quatre fois moins élevée que celle de la vipère aspic.\nLes juvéniles sont actifs de juillet à septembre, parfois octobre. Les femelles sont actives de mai, parfois avril, à septembre/octobre. Les mâles sont actifs sur la même période, mais parfois à partir de mars."}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nConsultation dans la structure de soins la plus proche."}, {"h": "Prise en charge médicale", "body": "La vipère d'Orsini dispose de crochets venimeux. Son venin est néanmois le moins puissant de toutes les vipères françaises.\nA ce jour, aucun cas d'envenimation nécessitant hospitalisation n'a été répertorié."}], "danger_class": "moderate", "danger_short": "Potentiellement venimeux"}, {"id": "vipere-de-seoane", "name": "Vipère de Séoane", "category": "menu-serpents", "category_title": "Serpents de France métropolitaine", "danger": "Venimeux\nSyndrome vipérin", "id_screen": "vipère seoane 1", "info_screen": "vipère seoane 2", "images": ["ResFile1474460479100.webp", "ResFile14744605641.webp", "ResFile147446057584.webp", "ResFile11473160552.webp"], "syndrome": "syndrome-viperin", "sections": [{"h": "Vipère de Séoane\n(Vipera seoanei)", "body": "Ce serpent venimeux présent dans le sud ouest de la France est diurne (mais devient nocturne aux fortes chaleurs) et vatteint en général entre 40 et 50 cm. Il est très variable dans ses couleurs et motifs, en général beige, marron ou gris avec en général une bande dorsale aux bordures irrégulières. Ses écailles sont fortement carénées, et il a une tête triangulaire, aux yeux à la pupille fendue verticalement. Il fréquente les bois, landes, ronciers et clairières mais évite les zones trop sèches et très rocailleuses, jusqu'à 1 900 m dans les montagnes de la côte de Cantabrie, et se nourrit de petits mammifères, oiseaux et reptiles. Les femelles se reproduisent en général une fois tous les deux ans et donnent naissance à la fin de l'été"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nConsulter le centre de soins le plus proche.\nNe pas garroter."}, {"h": "Prise en charge médicale", "body": "La vipère de Seoane est venimeuse et dangereuse."}], "danger_class": "danger", "danger_short": "Venimeux"}, {"id": "vipere-peliade", "name": "Vipère péliade", "category": "menu-serpents", "category_title": "Serpents de France métropolitaine", "danger": "Venimeux\nSyndrome vipérin", "id_screen": "Vipère péliade 1", "info_screen": "Vipère péliade 2", "images": ["ResFile147446036665.webp", "ResFile147446037760.webp", "ResFile147446038961.webp", "ResFile147446040055.webp"], "syndrome": "syndrome-viperin", "sections": [{"h": "Vipère péliade\n(Vipera berus)", "body": "La vipère péliade, dont le corps est relativement large, peut atteindre 60 cm à l'âge adulte mais a en moyenne une longueur de 55 cm, cette taille variant selon la localité\nLa vipère péliade vit dans les landes, les lieux boisés, les champs ou prés humides. Elle affectionne les lieux géographiques tempérés et pas trop secs\nIl existe une seule période d 'accouplement, au printemps."}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nConsulter la structure de soins la plus proche.\nNe pas garroter."}, {"h": "Prise en charge médicale", "body": "La vipère péliade est un serpent venimeux, dont l'envenimation peut être grave."}], "danger_class": "danger", "danger_short": "Venimeux"}, {"id": "veuve-noire-d-europe", "name": "Veuve noire d'Europe", "category": "menu-araignees", "category_title": "Araignées de France", "danger": "Venimeux\nLatrodectisme", "id_screen": "malmignatte 1", "info_screen": "Malmignatte 2", "images": ["ResFile147626163845.webp", "ResFile147626163074.webp"], "syndrome": "latrodectisme", "sections": [{"h": "Veuve noire d'Europe\n(Latrodectus tredecimguttatus)", "body": "La Veuve noire méditerranéenne ou Veuve noire d'Europe, aussi appellé latrodecte à 13 points ou Malmignatte, se rencontre surtout dans le sud du pays et en Corse.\nElle est de couleur noire, et s'identifie par les treize points qui ornent le dos de son abdomen. Ces points sont habituellement rouges, mais peuvent aussi être jaunes ou orange.\n\nA noter que les morsures ont généralement lieu au printemps/été et dans des milieux ruraux/naturels."}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nConsulter dans la structure de soins la plus proche"}, {"h": "Prise en charge médicale", "body": "Les veuves noires d'Europe sont responsable d'une forme très atténuée de latrodectisme. Aucun décès n'a été objectivé. Le latrodectisme des veuves noires d'Amerique correspond à la description qui suit."}], "danger_class": "danger", "danger_short": "Venimeux"}, {"id": "steatoda", "name": "Steatoda", "category": "menu-araignees", "category_title": "Araignées de France", "danger": "Venimeux\nSteatodisme", "id_screen": "steatoda 1", "info_screen": "Steatoda 2", "images": ["ResFile147627184951.webp", "ResFile147627185716.webp"], "syndrome": "steatodisme", "sections": [{"h": "Genre Steatoda\n(Steatoda)", "body": "Le genre Steatoda, proche du genre Latrodectus, regroupe plusieurs types d'araignées vivant sous nos latitudes, généralement connues sous le nom de \"fausses veuves noires\"\n\nBien qu'habituellement peu aggressives, les morsures sont possibles à toutes périodes de l'année."}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nConsulter une structure de soins"}, {"h": "Prise en charge médicale", "body": "Les steatoda sont venimeuses mais représentent plus de l'inconfort qu'un réél danger."}], "danger_class": "danger", "danger_short": "Venimeux"}, {"id": "araignee-violon", "name": "Araignée-violon", "category": "menu-araignees", "category_title": "Araignées de France", "danger": "Venimeux\nLoxoscelisme", "id_screen": "Araignée-violon 1", "info_screen": "Araignée violon 2", "images": ["ResFile147626153496.webp", "ResFile147626151423.webp"], "syndrome": "loxocelisme", "sections": [{"h": "Araignée-violon\n(Loxosceles rufescens)", "body": "Loxosceles rufescens est de couleur brune, et un corps en forme de violon.\nLa plupart de ces araignées ont une tache panduriforme sur leur carapace et une rainure longitudinale. Elle a six yeux et des poils nets sur le corps et les pattes.\nElle se rencontre volontiers dans les maisons"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nConsulter la structure de soins la plus proche"}, {"h": "Prise en charge médicale", "body": "L'araignée-violon est venimeuse et potentiellement dangereuse."}], "danger_class": "danger", "danger_short": "Venimeux"}, {"id": "hogna", "name": "Hogna", "category": "menu-araignees", "category_title": "Araignées de France", "danger": "Venimeux\nNécrose locale", "id_screen": "Hogna 1", "info_screen": "Hogna 2", "images": ["ResFile147628045995.webp", "ResFile14762804687.webp"], "syndrome": "araneisme-necosant", "sections": [{"h": "Hogna\n(Hogna radiata)", "body": "En France, elle se répartit sur le Bassin méditerranéen, où elle est présente surtout dans le Languedoc-Roussillon. Elle peut remonter sur la façade atlantique, parfois jusqu'au Bassin parisien. Le plus souvent, les individus rencontrés loin de son principal lieu de répartition, le Midi, appartiennent à la sous-espèce Hogna radiata minor, plus petite que sa cousine Hogna radiata radiata.\n\nLes mâles mesurent de 15 à 18 mm et les femelles de 20 à 25 mm"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie."}, {"h": "Prise en charge médicale", "body": "La lycose dispose d'un venin nécrosant, dont la toxicité est locale chez l'homme.\nAntiseptiques +/- VAT"}], "danger_class": "danger", "danger_short": "Venimeux"}, {"id": "lycoses", "name": "Lycoses", "category": "menu-araignees", "category_title": "Araignées de France", "danger": "Venimeux\nNécrose locale", "id_screen": "Lycosa 1", "info_screen": "Lycosa 2", "images": ["ResFile14762799614.webp", "ResFile147627995327.webp"], "syndrome": "araneisme-necosant", "sections": [{"h": "Lycose\n(Lycosa tarantula ou Lycosa narbonensis)", "body": "Cette espèce se rencontre dans le Sud de la France, en Italie, dans les Balkans et au Proche-Orient.\n\nElle affectionne les plaines arides, caillouteuses, avec une végétation rase et éparse. Les garrigues sèches sont son milieu de prédilection, elle est très commune dans la plaine de la Crau."}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie."}, {"h": "Prise en charge médicale", "body": "La lycose dispose d'un venin nécrosant, dont la toxicité est locale chez l'homme.\nLa morsure est très douloureuse, mais ne présente pas de danger.\nAntiseptiques +/- VAT"}], "danger_class": "danger", "danger_short": "Venimeux"}, {"id": "segestrie-florentine", "name": "Ségestrie florentine", "category": "menu-araignees", "category_title": "Araignées de France", "danger": "Venimeux\nNécrose locale", "id_screen": "Segestries 1", "info_screen": "Segestrie 2", "images": ["ResFile147626141629.webp", "ResFile147626143279.webp"], "syndrome": "araneisme-necosant", "sections": [{"h": "Ségestrie florentine\n(Segestria florentina)", "body": "Segestria florentina est une grosse araignée noire avec des chélicères bien visibles, dont les reflets iridescents sont caractéristiques. Les femelles peuvent mesurer jusqu'à 22 mm. Malgré sa taille, cette araignée n'est pas vraiment dangereuse pour les humains, hormis un risque d'enflure ou de nécrose de la plaie"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nConsulter un médecin si aggravation de la plaie"}, {"h": "Prise en charge médicale", "body": "La ségestrie florentine dispose d'un venin nécrosant, dont la toxicité est locale chez l'homme. A noter, le venin provoque des paralysies flasque chez l'animal, via une action neurotoxique\nAntiseptiques +/- VAT"}], "danger_class": "danger", "danger_short": "Venimeux"}, {"id": "tegenaires", "name": "Tégénaires", "category": "menu-araignees", "category_title": "Araignées de France", "danger": "Venimeux\nNécrose locale", "id_screen": "Tegenaires 1", "info_screen": "Tegenaires 2", "images": ["ResFile147626124685.webp", "ResFile147626128080.webp"], "syndrome": "araneisme-necosant", "sections": [{"h": "Tégénaires\n(Tegenaria)", "body": "Tegenaria est un genre d'araignées aranéomorphes de la famille des Agelenidae.\nCes araignées, de couleur brun foncé à noir, mesurent de 20 à 25 mm pour les plus grandes espèces ; avec les pattes, elles font facilement plus de 5 cm, parfois 10 cm.\n\nLe mâle adulte se reconnaît à la présence d'organes d'accouplement, appelés bulbes copulateurs, situés au bout des pédipalpes.\n\nCes arachnides sont pratiquement aveugles mais perçoivent les vibrations les plus minimes. Ce sont aussi elles que l'on rencontre le plus souvent dans les baignoires ou les éviers des maisons car elles n'arrivent pas à escalader des parois aussi lisses."}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie."}, {"h": "Prise en charge médicale", "body": "La tégénaire dispose d'un venin nécrosant, dont la toxicité est locale chez l'homme.\nAntiseptiques +/- VAT"}], "danger_class": "danger", "danger_short": "Venimeux"}, {"id": "epeires", "name": "Epeires", "category": "menu-araignees", "category_title": "Araignées de France", "danger": "Inoffensif", "id_screen": "Epeires 1", "info_screen": "Epeire 2", "images": ["ResFile147626051480.webp", "ResFile147626053668.webp"], "syndrome": null, "sections": [{"h": "Epeires\n(Epeira)", "body": "Le genre \"épeires\" regroupe un certain nombre d'espèces dont l'une des particularités est la création de toiles très grandes par rapport à sa propre taille, puisqu'elles peuvent atteindre exceptionnellement un mètre, avec des fils particulièrement solides qui craquent sèchement (bruit de \"perle\") lorsqu'ils rompent. La toile est refaite tous les jours : l'épeire ne répare pas sa toile et la recommence tous les matins"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie."}, {"h": "Prise en charge médicale", "body": "Les épeires, bien qu'impressionnantes, ne représentent aucun danger pour l'homme.\nAntiseptiques"}], "danger_class": "safe", "danger_short": "Inoffensif"}, {"id": "pholques", "name": "Pholques", "category": "menu-araignees", "category_title": "Araignées de France", "danger": "Inoffensif", "id_screen": "Pholques 1", "info_screen": "Pholques 2", "images": ["ResFile147626115435.webp", "ResFile147626117719.webp"], "syndrome": null, "sections": [{"h": "Les pholques\n(Pholcus)", "body": "C'est une araignée typique des maisons. Cette espèce se reconnaît aisément à ses pattes très longues, qui lui donne l'air d'un faucheux. Le Pholque phalangide réside dans les caves, dans les coins des pièces, en haut des fenêtres où il tisse une toile irrégulière. Il s'y tient accroché à l'envers, l'abdomen pointant vers le haut.\nComme toutes les araignées, cette espèce est prédatrice et se nourrit de petits insectes volants se prenant à sa toile. À l'occasion, elle s'attaque aussi à des animaux marchant qui rencontrent les fils de sa toile. Ainsi une tégénaire, araignée pourtant plus grosse et d'apparence plus robuste, n'a aucune chance contre lui. Le Pholque phalangide n'hésite pas à s'attaquer aux guêpes isolées qui s'aventurent dans les habitations, l'araignée emmaillote alors la guêpe en quelques fractions de seconde pendant que celle-ci marche sur une surface, une vitre par exemple."}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie."}, {"h": "Prise en charge médicale", "body": "Les pholques ne représentent aucun danger pour l'homme, alors que paradoxalement, ce sont des araignées très venimeuses pour les autres insectesL\nAntiseptiques"}], "danger_class": "safe", "danger_short": "Inoffensif"}, {"id": "autres-araignees", "name": "AUTRES ARAIGNEES", "category": "menu-araignees", "category_title": "Araignées de France", "danger": "Désinfecter/nettoyer. Pas de danger avec les autres araignées.", "id_screen": null, "info_screen": null, "images": [], "syndrome": null, "sections": [{"h": null, "body": "Désinfecter/nettoyer. Pas de danger avec les autres araignées."}], "danger_class": "neutral", "danger_short": "Désinfecter/nettoyer. Pas de danger avec les autres araignées."}, {"id": "scorpion-jaune-du-languedoc", "name": "Scorpion jaune du Languedoc", "category": "menu-scorpions", "category_title": "Scorpions de France", "danger": "Théoriquement venimeux\nScorpionisme", "id_screen": "Scorpions jaune 1", "info_screen": "Scorpion jaune 2", "images": ["ResFile147627198383.webp", "ResFile147627197250.webp"], "syndrome": "syndrome-scorpionique", "sections": [{"h": "Scorpion Languedocien\n(Buthus occitanus)", "body": "Le scorpion languedocien est le plus grand scorpion européen (8 cm des pinces à l'extrémité de la queue), sa couleur est uniformément jaune.\n\nLa piqûre de la population française est très douloureuse, mais pas mortelle.\nNocturne, il passe ses journées sous une pierre dans la garrigue, et chasse surtout les araignées."}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nEn référer à un médecin"}, {"h": "Prise en charge médicale", "body": "Le scorpion jaune est le seul scorpion en France a disposer de venin. Néanmois, aucun cas mortel n'a été répertorié.\nPiqure très douloureuse."}], "danger_class": "moderate", "danger_short": "Théoriquement venimeux"}, {"id": "scorpion-noir-a-pattes-jaunes", "name": "Scorpion noir à pattes jaunes", "category": "menu-scorpions", "category_title": "Scorpions de France", "danger": "Inoffensif", "id_screen": "Scorpion noir 1", "info_screen": "Scorpion noir 2", "images": ["ResFile147627606737.webp", "ResFile147627607653.webp"], "syndrome": null, "sections": [{"h": "Scorpion noir\n(Euscorpius flavicaudis)", "body": "Il est caractérisé par sa couleur noire et ses pattes qui vont du jaune paille au jaune or. L'adulte mesure de 35 à 45 millimètres de long. Cette espèce aime l'humidité. Il n'est pas dangereux pour l'homme, on peut le rencontrer en ville. Il se cache souvent sous les tuiles ou les pierres des vieilles maisons"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nEn référer à un médecin"}, {"h": "Prise en charge médicale", "body": "Le venin ne presente pas de danger pour l'homme.\nPiqure très douloureuse.\nAntiseptiques +/- VAT +/- ATB"}], "danger_class": "safe", "danger_short": "Inoffensif"}, {"id": "euscorpius-carpathicus", "name": "Euscorpius carpathicus", "category": "menu-scorpions", "category_title": "Scorpions de France", "danger": "Inoffensif", "id_screen": "Euscorpius carpathicus 1", "info_screen": "Euscorpius carpathicus 2", "images": ["ResFile147627638551.webp", "ResFile147627639318.webp"], "syndrome": null, "sections": [{"h": "Euscorpius carpathicus", "body": "Euscorpius carpathicus est une espèce de scorpions sans grandes particularités, et inoffensive"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nEn référer à un médecin"}, {"h": "Prise en charge médicale", "body": "Le venin ne presente pas de danger pour l'homme.\nAntiseptique +/- VAT +/- ATB"}], "danger_class": "safe", "danger_short": "Inoffensif"}, {"id": "euscorpius-italicus", "name": "Euscorpius italicus", "category": "menu-scorpions", "category_title": "Scorpions de France", "danger": "Inoffensif", "id_screen": "Euscorpius italicus 1", "info_screen": "Euscorpius italicus 2", "images": ["ResFile147627657270.webp", "ResFile147627656697.webp"], "syndrome": null, "sections": [{"h": "Euscorpius italicus", "body": "Euscorpius italicus est une espèce de scorpions sans grandes particularités, et inoffensive"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nEn référer à un médecin"}, {"h": "Prise en charge médicale", "body": "Le venin ne presente pas de danger pour l'homme.\nAntiseptiques +/- VAT +/- ATB"}], "danger_class": "safe", "danger_short": "Inoffensif"}, {"id": "belisarius-xambeui", "name": "Belisarius Xambeui", "category": "menu-scorpions", "category_title": "Scorpions de France", "danger": "Inoffensif", "id_screen": "Belisarius Xambeui 1", "info_screen": "Belisarius Xambeui 2", "images": ["ResFile147627682794.webp", "ResFile147627677079.webp"], "syndrome": null, "sections": [{"h": "Belisarius Xambeui", "body": "Cette espèce se rencontre dans les Pyrénées, entre 650 et 1 500 m d'altitude, en Catalogne en Espagne et dans les Pyrénées-Orientales en France et vit dans les grottes.\nEn plus d'être inoffensive, elle ne présente pas d'yeux (Anophtalme)"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nEn référer à un médecin"}, {"h": "Prise en charge médicale", "body": "Le venin ne presente pas de danger pour l'homme.\nAntiseptiques +/- VAT +/- ATB"}], "danger_class": "safe", "danger_short": "Inoffensif"}, {"id": "hymenopteres", "name": "Hyménoptères", "category": "menu-insectes-volants", "category_title": "Insecte volant", "danger": "Abeilles - bourdons - guèpes - frelons - polistes", "id_screen": "Hymenoptères", "info_screen": "hyménoptères 2", "images": ["hymeno_abeille.webp", "ResFile147446167232.webp", "ResFile147446168019.webp", "ResFile147446168677.webp", "ResFile147446169580.webp"], "syndrome": "syndrome-hymenoptere", "sections": [{"h": "Les hyménoptères", "body": "Les hyménoptères (Hymenoptera) sont un ordre d'insectes, sous-classe des ptérygotes, section des néoptères, super-ordre des mécoptéroïdés. Des représentants communs de cet ordre sont les abeilles, les guêpes et les fourmis, présentes sur tous les continents sauf l'Antarctique. Les hyménoptères constituent, après les coléoptères, l'ordre d'insectes le plus diversifié et on estime actuellement qu'il y a plus de 230 000 espèces décrites.\n\nLes hyménoptères sont des insectes holométaboles d'une taille comprise entre 0,1 mm et 10 cm, pourvus de quatre ailes membraneuses couplées en vol et de pièces buccales du type broyeur-lécheur. La tête est séparée du thorax par un cou très mince et très mobile. Leur métathorax est très court, soudé au premier segment abdominal pour former le segment médiaire. Ces insectes sont aisément identifiables dans l'ordre des hyménoptères."}, {"h": "Prise en charge non médicale", "body": "Approcher d'une source de chaleur puis d'une source de froid (choc thermique)\nRetirer le dard (abeilles et bourdons).\nDésinfecter et nettoyer la piqure\n\nConsulter un médecin si :\n- Allergie connue a l'insecte\n- Piqures multiples\n- Piqure dans la bouche, sur des muqueuses\n- Apparition de signes généraux"}, {"h": "Prise en charge médicale", "body": ""}], "danger_class": "neutral", "danger_short": "Abeilles - bourdons - guèpes - frelons - polistes"}, {"id": "reduves", "name": "Réduves", "category": "menu-insectes-volants", "category_title": "Insecte volant", "danger": "", "id_screen": null, "info_screen": "Reduve 2", "images": ["reduve_1.webp", "reduve_2.webp", "reduve_3.webp", "reduve_4.webp"], "syndrome": null, "sections": [{"h": "Les réduves", "body": "Les réduves (Reduviidae) forment une grande famille qui regroupe 5500 espèces dans le monde, dont la réduve masquée, célèbre par son camouflage fait de poussières. La réduve se distingue entre autres par son rostre piqueur fort.\nElles ne disposent pas de venin.\n\nCertaines réduves d'Amérique latine (punaises du genre Panstrongylus, Triatoma ou Rhodnius) sont vecteurs de maladies, notamment la maladie de Chagas"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie."}, {"h": "Prise en charge médicale", "body": "Les réduves sont hematophages et ne disposent pas de venin.\nLa piqure est a risque de surinfection et doit être surveillée.\nAntiseptiques + surveillance"}], "danger_class": "neutral", "danger_short": "—"}, {"id": "taons", "name": "Taons", "category": "menu-insectes-volants", "category_title": "Insecte volant", "danger": "", "id_screen": null, "info_screen": "Taons 2", "images": ["taon_1.webp", "taon_2.webp", "taon_3.webp", "taon_4.webp"], "syndrome": null, "sections": [{"h": "Les taons", "body": "Les Tabanidae constituent une famille d'insectes diptères renfermant diverses espèces de taons.\n\nCe sont des mouches trapues aux grands yeux composés. Les femelles se nourrissent normalement du sang des grands mammifères qu'elles mordent avec leur stylet alors que les mâles ne consomment que du nectar. Ces insectes sont pratiquement tous diurnes. On dénombre environ 3 500 espèces dans cette famille dont près de 160 en Europe, dont Tabanus bovinus en France.\n\nContrairement à un lieu commun répandu, les taons mordent, ils ne piquent pas. Ils arrachent ou découpent la chair de leur victime au moyen de mandibules. La plaie ainsi ouverte laisse perler le sang que le taon pourra alors sucer à loisir. Il lui arrive même parfois de détacher un morceau entier de chair pour le digérer lentement.\n\nSous d'autres latitudes, les taons peuvent être des vecteurs parasitaires"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nConsulter un médecin si apparition de signes généraux, allergies ou infection"}, {"h": "Prise en charge médicale", "body": "Le taon ne dispose ni de dard ni de venin. Il mord.\nLa prise en charge repose sur le traitement symptomatique (pouvant aller jusqu'a la prise en charge d'un choc anaphylactique), et sur la surveillance de l'apparition d'une eventuelle surinfection"}], "danger_class": "neutral", "danger_short": "—"}, {"id": "vives", "name": "Vives", "category": "menu-animaux-marins", "category_title": "Animaux marins", "danger": "Pas de risque vital", "id_screen": null, "info_screen": "Vive 2", "images": ["vive_1.webp", "vive_2.webp", "vive_3.webp", "vive_4.webp"], "syndrome": null, "sections": [{"h": "Les vives\n(Trachinidae)", "body": "Les vives ont pour point commun de posséder une épine dorsale venimeuse. Certaines présentent des rayons épineux qui peuvent blesser et qui sont venimeux. Ces poissons, qui vivent juste sous la surface du sable, piquent l'Homme lorsque celui-ci leur marche dessus. La piqûre se sent très fort puis une grosse douleur commence et se propage, la douleur va jusqu'aux os.\n\nLe venin est injecté par l'épine dorsale et deux épines operculaires. Même mort, ce poisson reste dangereux. La douleur est \"vive\", très violente et instantanée. Elle irradie jusqu'à la racine du membre piqué. Elle peut entraîner une véritable infection."}, {"h": "Prise en charge non médicale", "body": "Lors d'une piqûre de vive, sortez de l'eau et retirez immédiatement les fragments. Désinfectez la plaie.\n\nLe venin étant détruit par la chaleur (propriété thermolabile), l'un des traitements possible consiste à tremper le membre atteint dans de l'eau chaude à 40 °C pendant trente minutes, l'eau chaude permettant par ailleurs de dilater les pores de la peau pour mieux évacuer le venin."}, {"h": "Prise en charge médicale", "body": "Le pronostic vital n'est pas engagé.\nLe risque est lié aux eventuelles réactions anaphylactiques, et aux risques de surinfections.\nAntiseptiques\nUne hospitalisation sera indiquée s'il existe une piqure au niveau d'une articulation ou d'une zone charnière"}], "danger_class": "safe", "danger_short": "Pas de risque vital"}, {"id": "meduses", "name": "Méduses", "category": "menu-animaux-marins", "category_title": "Animaux marins", "danger": "Pas de risque vital en France", "id_screen": null, "info_screen": "Meduses 2", "images": ["meduse_1.webp"], "syndrome": null, "sections": [{"h": "Les méduses\n(cnidaires)", "body": "Les méduses piquent leur proie en utilisant leurs tentacules extensibles qui portent par millions des nématocystes groupés en batteries urticantes qui injectent du venin en provoquant de multiples micro-piqûres\n\nAttention, plusieurs espèces de méduses, notamment les cuboméduses (quelques mètres) ou les Sea Wasp/Irukanji (quelques millimètres) peuvent être mortelles pour l'homme, mais elles ne sont pas rencontrées sur nos littoraux."}, {"h": "Prise en charge non médicale", "body": "Rincer à l'eau de mer, alcool ou vinaigre.\nRecouvrir de sable, SANS FROTTER, et enlever à l'aide d'une carte.\nNe pas hésiter à faire 2, 3 rinçages.\nDésinfection et nettoyage de la plaie.\nComme pour les vives, le venin est thermolabile\nConsulter un médecin si apparition de signes généraux"}, {"h": "Prise en charge médicale", "body": "Aucune méduse française ne représente de danger vital pour l'homme.\nNeanmoins une réaction anaphylactique au venin est toujours possible"}], "danger_class": "safe", "danger_short": "Pas de risque vital en France"}, {"id": "anemones", "name": "Anémones", "category": "menu-animaux-marins", "category_title": "Animaux marins", "danger": "Pas de risque vital", "id_screen": null, "info_screen": "Anemones 2", "images": ["anemone_1.webp"], "syndrome": null, "sections": [{"h": "Anémones de mer\n(Actiniaria)", "body": "Ce sont des polypes solitaires sans stade méduse, dépourvus d'exosquelette et dont la taille atteint de 1,25 cm à presque 2 m de diamètre. Les tentacules, habituellement nombreux, ont des nématocystes au poison urticant - mais seules certaines espèces sont douloureuses pour l'Homme.\n\nLeur anatomie montre un pied qui s'ancre dans le sable ou s'attache sur des substrats durs par adhésion comme une ventouse, surmonté d'un corps d'où rayonnent des tentacules lisses, pointus ou arrondis, disposés en cercles concentriques autour de la bouche, qui se trouve en position centrale"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nComme pour les vives, le venin est thermolabile"}, {"h": "Prise en charge médicale", "body": "Avec les espèces vivant sur les cotes françaises, le pronostic vital n'est pas engagé.\nNeanmoins une réaction anaphylactique au venin est toujours possible"}], "danger_class": "safe", "danger_short": "Pas de risque vital"}, {"id": "raies", "name": "Raies", "category": "menu-animaux-marins", "category_title": "Animaux marins", "danger": "Pas de risque vital en France", "id_screen": null, "info_screen": "Raies 2", "images": ["raie_1.webp", "raie_piqure_bastia.webp"], "syndrome": null, "sections": [{"h": "Les raies\n(Batoidea ou Rajomorphii)", "body": "Les raies ou batoïdes (Batoidea ou Rajomorphii) forment un super-ordre des poissons cartilagineux caractérisés par un corps aplati, de grandes nageoires pectorales solidaires du tronc et des fentes branchiales ventrales. Le super-ordre contient près de 500 espèces réparties en 13 familles.\n\nEn France metropolitaine, la pastenague peut se rencontrer ; la piqure est très douloureuse, mais pas dangereuse.\n\nUne toxicité systémique a été rapportée pour certaines espèces tropicales.\n\nIl existe des raies d'eau douce, notamment en Amérique du Sud (Espèce Potamotrygon) qui peuvent être responsables de cardiotoxicité et de neurotoxicité."}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\nRetirer l'aiguillon si besoin/\nMettre de l'eau chaude puis froide (le venin est thermolabile)"}, {"h": "Prise en charge médicale", "body": "Avec les espèces vivant sur les cotes françaises, le pronostic vital n'est pas engagé.\nLe risque est lié aux eventuelles réactions anaphylactiques, et aux risques de surinfections.\nAntiseptique"}], "danger_class": "safe", "danger_short": "Pas de risque vital en France"}, {"id": "rascasses", "name": "Rascasses", "category": "menu-animaux-marins", "category_title": "Animaux marins", "danger": "Pas de risque vital", "id_screen": null, "info_screen": "Rascasses 2", "images": ["rascasse_1.webp"], "syndrome": null, "sections": [{"h": "Les rascasses\n(Scorpaenidés)", "body": "Le mot Rascasse est un nom vernaculaire ambigu en français, pouvant désigner plusieurs espèces différentes de poissons réparties dans plusieurs genres, principalement de la famille des scorpaenidés.\nCe sont dans l'ensemble surtout des poissons de fonds rocheux au corps massif avec des lambeaux de peau, aux nageoires épineuses ainsi que la tête, elle-même dotée d'une large bouche"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie.\n\nLe venin est thermolabile ; un choc thermique diminue donc la symptomatologie."}, {"h": "Prise en charge médicale", "body": "Avec les espèces vivant sur les cotes françaises, le pronostic vital n'est pas engagé.\nLe risque est lié aux eventuelles réactions anaphylactiques, et aux risques de surinfections.\nAntiseptique."}], "danger_class": "safe", "danger_short": "Pas de risque vital"}, {"id": "le-poisson-globe-ou-fugu", "name": "Le poisson-globe ou Fugu", "category": "menu-animaux-marins", "category_title": "Animaux marins", "danger": "Cas particulier\nMortel si ingéré", "id_screen": null, "info_screen": "Fugu", "images": ["fugu_1.webp", "fugu_2.webp", "fugu_3.webp"], "syndrome": "tetrodotoxisme", "sections": [{"h": "Poisson-globe (Fugu)", "body": "Le Fugu (genre Takifugu) vit dans les eaux tempérées et tropicales de l'Indo-Pacifique ; il n'est habituellement consommé qu'au Japon ou dans certaines îles du Pacifique. En Méditerranée, le risque de tétrodotoxisme est porté par le poisson-lièvre (voir fiche dédiée), et non par ce poisson.\nIl se gonfle d'eau lorsqu'il se sent menacé, ce qui explique son nom de poisson-globe. Sa chair, son foie, ses gonades, ses intestins et sa peau peuvent contenir de la tétrodotoxine."}, {"h": "Prise en charge médicale", "body": "L'intoxication survient par ingestion de chair ou d'abats contaminés par la tétrodotoxine (pas d'envenimation par piqûre)."}], "danger_class": "danger", "danger_short": "Cas particulier"}, {"id": "poisson-lievre", "name": "Poisson-lièvre", "category": "menu-animaux-marins", "category_title": "Animaux marins", "danger": "Cas particulier\nMortel si ingéré", "syndrome": "tetrodotoxisme", "id_screen": null, "info_screen": null, "images": ["lievre_1.webp", "lievre_2.webp"], "sections": [{"h": "Poisson-lièvre\n(Lagocephalus sceleratus)", "body": "Le poisson-lièvre (Lagocephalus sceleratus) est un tétraodontidé originaire de l'Indo-Pacifique, entré en Méditerranée par le canal de Suez. Il y est aujourd'hui invasif et en pleine expansion, ce qui en fait le principal porteur de tétrodotoxine sous nos latitudes.\nCorps allongé et argenté, dos vert-olive semé de points noirs, flancs à ligne claire ; il peut dépasser 40 cm.\n\nContrairement au poisson-globe (Fugu) — consommé surtout au Japon et dans le Pacifique —, le poisson-lièvre est présent et pêché en Méditerranée : sa consommation, comme celle de coquillages ayant accumulé la toxine, fait craindre l'apparition de cas de tétrodotoxisme en France métropolitaine.\nSource : thèse du Dr Pierrick Gouel (Faculté de médecine des Antilles et de la Guyane, 2021)."}, {"h": "Prise en charge médicale", "body": "L'intoxication survient par ingestion de chair ou d'abats contaminés par la tétrodotoxine (pas d'envenimation par piqûre)."}], "danger_class": "danger", "danger_short": "Cas particulier"}, {"id": "autres-envenimations-et-toxines", "name": "Autres envenimations et toxines", "category": "menu-animaux-marins", "category_title": "Animaux marins", "danger": "Il en existe beaucoup, mais non décrites sous nos latitudes", "id_screen": null, "info_screen": null, "images": [], "syndrome": null, "sections": [{"h": null, "body": "Il en existe beaucoup, mais non décrites sous nos latitudes"}], "danger_class": "neutral", "danger_short": "Il en existe beaucoup, mais non décrites sous nos latitudes"}, {"id": "crapaud-commun", "name": "Crapaud commun", "category": "menu-batraciens", "category_title": "Batraciens", "danger": "Pas de risque vital", "id_screen": "Crapaud", "info_screen": "Crapaud 2", "images": ["ResFile147628692977.webp", "ResFile147628693735.webp"], "syndrome": null, "sections": [{"h": "Le crapaud commun\n(Bufo Bufo)", "body": "Crapaud commun, est une espèce d'amphibiens de la famille des Bufonidae. C'est l'espèce de crapauds la plus répandue en Europe.\nSur le dos, sa peau est pustuleuse, c'est-à-dire couverte de saillies (appelées aussi verrues) formées par des glandes granuleuses, capables de secréter un venin crémeux, contenant des amines, des peptides et des alcaloïdes.\nLe venin des glandes parotoïdes et des pustules a pour fonction de protéger les crapauds contre les prédateurs et joue aussi un rôle antiseptique et antibiotique pour un animal qui ne possède pas un système immunitaire aussi performant que celui des mammifères. Ce poison n'est dangereux que pour les carnassiers qui veulent le mordre, sauf les serpents réfractaires au venin. Certaines glandes secrètent un mucus lui permettant de ne pas se dessécher et de préserver ainsi l'humidité et l'élasticité de sa peau."}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la zone touchée par le venin"}, {"h": "Prise en charge médicale", "body": "Le venin de crapaud contient des bufotoxines, aux propriétés cardiotoxiques (mecanisme = hyperkaliemie via un effet digitaline-like)\n\nSi le simple contact avec le venin n'est pas dangereux pour l'homme, l'ingestion et/ou la consommation de la peau peut mener à de graves envenimations"}], "danger_class": "safe", "danger_short": "Pas de risque vital"}, {"id": "salamandre-tachetee", "name": "Salamandre tachetée", "category": "menu-batraciens", "category_title": "Batraciens", "danger": "Pas de risque vital", "id_screen": "Salamandre", "info_screen": "Salamandre 2", "images": ["ResFile14762869838.webp", "ResFile147628699075.webp"], "syndrome": null, "sections": [{"h": "Salamandre tachetée\n(Salamandra salamandra)", "body": "La peau épaisse et brillante de la salamandre tachetée est munie de nombreuses glandes qui sécrètent une fine couche de mucus empoisonné par une neurotoxine qui agit par contact avec les muqueuses. Les sécrétions produites par les glandes des salamandres tachetées sont classées parmi les alcaloïdes. Jusqu'ici les composés organiques Samandarin (C19H31NO), Samandaridin (C21H31NO) et Samanderon (C22H31N02) ont été identifiés. (mecanisme : blocage des canaux calciques)\n\nNormalement, ces sécrétions provoquent seulement une légère brûlure - si réaction il y a - sur la peau humaine. Sur des personnes sensibles, ces sécrétions peuvent provoquer des nausées, des troubles respiratoires et des vomissements"}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la zone en contact avec le venin\nConsulter un médecin s'il existe un contact muqueux"}, {"h": "Prise en charge médicale", "body": "La salamandre tachetée ne présente theoriquement aucun risque vital (en dehors des eventuelles reactions d'hypersensibilité)\nUn contact muqueux prolongé peut justifier une surveillance hospitalière"}], "danger_class": "safe", "danger_short": "Pas de risque vital"}, {"id": "scolopendre", "name": "Scolopendre", "category": "menu-autres", "category_title": "Autres", "danger": "Pas de risque vital", "id_screen": null, "info_screen": "Scolopendre 2", "images": ["scolopendre_1.webp", "scolopendre_2.webp"], "syndrome": null, "sections": [{"h": "Scolopendre", "body": "Scolopendra est un genre de myriapodes chilopodes de la famille des Scolopendridae. La scolopendre est un animal carnassier et parfois venimeux.(venin : histamine, sérotonine, cardiotoxine)\n\nLa morsure des scolopendres peut être très douloureuse, notamment celle des espèces tropicales, avec œdème et parfois nécrose cutanée autour de la morsure.\n\nScolopendra cingulata est répandue sur tout le contour de la mer Méditerranée. Scolopendra gigantea, rencontrée en Amérique du Sud, est l'espèce la plus grande et peut atteindre jusqu'à 40 cm de long. La scolopendre peut s'introduire dans les maisons."}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie."}, {"h": "Prise en charge médicale", "body": "Le scolopendre dispose d'un venin très douloureux, mais pas dangereux sous nos latitudes\nAntiseptiques +/- VAT"}], "danger_class": "safe", "danger_short": "Pas de risque vital"}, {"id": "aoutat", "name": "Aoutat", "category": "menu-autres", "category_title": "Autres", "danger": "Inoffensif", "id_screen": null, "info_screen": "Aoutats 2", "images": ["aoutat_1.webp", "aoutat_2.webp"], "syndrome": null, "sections": [{"h": "Aoûtat\n(Trombicula autumnalis)", "body": "L'aoûtat désigne la larve d'une espèce de petit acarien de la famille des Trombiculidés : Trombicula autumnalis, appelé aussi rouget, vendangeon ou vendangeron.\n\nLa larve de cet arthropode acarien parasite temporairement les organismes à sang chaud et occasionne par ses piqûres des démangeaisons parfois importantes chez son hôte."}, {"h": "Prise en charge non médicale", "body": "Désinfection et nettoyage de la plaie."}, {"h": "Prise en charge médicale", "body": "L'aoutat ne dispose pas de venin.\nLe risque est lié a la sur-infection des plaies\nTraitement symptomatique + antiseptiques"}], "danger_class": "safe", "danger_short": "Inoffensif"}], "syndromes": [{"id": "syndrome-cobraique", "name": "Syndrome cobraïque", "header": "Evenimation : syndrome cobraïque", "images": [], "sections": [{"h": null, "body": "Contrairement au venin des vipéridés, qui contient principalement des enzymes protéaolytiques, le venin des élapidés a une toxicité directe ; principalement neurologique, mais aussi cardiaque et rénale.\nLa toxicité est dose dépendante.\n\nOn individualise 3 type de toxines :\n- les β-neurotoxines pré-synaptiques (Inhibition du recyclage de l’acétylcholine, donc majoration de l'effet des neurotoxines post-synaptiques)\n\n- les α-neurotoxines post-synaptiques (blocage des recepteurs muscariniques)\n\n- Les toxines dépolarisantes (dendrotoxine et fasciculine. Ces toxines provoquent un syndrome muscarinique et une dépolarisation post-synaptique permanente)"}, {"h": "Grade 0", "body": "Aucun\n\nGeneralement, peu ou pas de réaction locale\n\nAprès la morsure : mise au repos de la victime et immobilisation du membre\nPoser une bande (pas de garrot) pour comprimer le système lymphatique sans comprimer le système vasculaire"}, {"h": "Grade 1", "body": "Apparition de signes neurologiques :\n- Ptosis, diplopie, ophtalmoplégie, dysphonie, troubles de la déglutition et atteinte des paires craniennes\n\nGeneralement, peu ou pas de réaction locale"}, {"h": "Grade 2", "body": "Majoration des signes neurologiques :\n- Ptosis, diplopie, ophtalmoplégie, dysphonie, troubles de la déglutition et atteinte des paires craniennes avec notamment disparition de la mimique.\n- Paresthesies diffuses et hypoesthesies\n- Ces manifestations peuvent s'accompagner ou etre precédées d'un syndrome muscarinique en cas de morsure de Mamba (soif , salivation, nausées et d'un myosis)\n\nSur le plan biologique, on retrouve :\n- augmentation des CPK, myoglobinurie, insuffisance renale aigue, syndrome de lyse avec hyperkaliémie\n\nSur le plan cardiaque :\n- la toxicité est rythmique, avec pour certaines espèces un BAV et des troubles de la repolarisation\n\nPRISE EN CHARGE REANIMATOIRE\nANTIVENIN ADMINISTRE SUR 20-30min, A POURSUIVRE JUSQU'A DISPARITION DES SIGNES NEUROLOGIQUES\n\nL'urgence est au maintien de la fonction respiratoire, avec oxygénotherapie, ventiliation assistée voire intubation si besion"}, {"h": "Grade 3", "body": "Detresse respiratoire\nComa, convulsions\n\nEtat de choc\n\nPRISE EN CHARGE REANIMATOIRE\nCATECHOLAMINES pour retablir stabilité hemodynamique , puis\nANTIVENIN ADMINISTRE SUR 20-30min, A POURSUIVRE JUSQU'A DISPARITION DES SIGNES NEUROLOGIQUES"}]}, {"id": "syndrome-viperin", "name": "Syndrome vipérin", "header": "Evenimation : syndrome vipérin", "images": [], "sections": [{"h": null, "body": "Les vipéridés sont de solénoglyphes. Les crochets sont repliés sur le palais, et se déploient a la morsures, permettant, ou non, l'injection sous pression de venin. La quantité de venin injectée est un choix de l'animal, ce qui veut dire que toute morsure ne s'accompagne pas forcement de l'injection de venin.\nPar contre, quand le venin est injecté, il l'est de manière pressurisée et profonde.\nLe venin est majoritairement composé de protéases, expliquant les réactions locales.\n(Vaspin, vipotoxine, ammodytoxine, PLA1)\nLa toxicité propre du venin de vipère est surtout liée a l'activité anticoagulante.\n\nDes anomalies biologiques de l'hémostase (non spécifiques) seront retrouvées, avec diminution du TP, du fibrinogène, etc...\nLa crainte sera l'évolution vers des saignements incoercibles, une CIVD et un choc.\nLes AINS sont contre-indiqués, et l'héparine aussi.\n\nMais on note, chez l'espèce Aspis, une recrudescence de la neurotoxicite du venin, avec un tableau allant jusqu'à une atteinte des paires craniennes (ptosis) voire une paralysie ascendante, et une detresse respiratoire.\nL'apparition d'un tableau neurologique correspond à un stade 2 d'emblée, necessitant un antidote et les mesures reanimatoires de la detresse respiratoire.\n\nCAS PARTICULIER :\nDans les Antilles, la Martinique est habitée par une espèce endémique de fer-de-lance appelée localement trigonocéphale (Bothrops lanceolatus). Ce serpent peu agressif est cependant responsable d’envenimations graves avec rapide mise en jeu du pronostic vital. Antidote specifique: Bothrofav.\nTableau de thromboses multiples."}, {"h": "Grade 0", "body": "Morsure sans envenimation (= morsure \"blanche\", dans 50% des cas)\nMarque des crochets, pas d'oedeme ou de réaction locale.\n\nDESINFECTION + SURVEILLANCE AUX URGENCES 6h"}, {"h": "Grade 1", "body": "Envenimation minime.\nOedeme local, pas de signes généraux\n\nDESINFECTION + TRAITEMENT SYMPTOMATIQUE + SURVEILLANCE HOSPITALIERE 24h\nBILAN BIO TOUTES LES 12h"}, {"h": "Grade 2", "body": "Envenimation modérée\n\n- 2a = Oedeme régional (membre mordu), hematome, suffusion, adénopathies satellites\n\n- 2b = Symptomes généraux modérés : hypotension, vomissements, diarrhée, signes neurotoxiques\net/ou\nCritères biologiques de sévérité :\n* Plaquettes < 150 G/L\n* Leucocytes >15 G/L\n* INR > 1.5\n* Fibrinogène < 2 g/L\n* TP < 60%\n\n- Tableau neurologique = équivalent grade 2 d'emblée (ptosis, détresse respiratoire)\n\nANTIVENIN VIPERFAV = 2 ampoules de 2mg dans 100-125ml sur 1H.\nRenouvellable à H4 si évolution défavorable\nSURVEILLANCE HOSPITALIERE"}, {"h": "Grade 3", "body": "Envenimation grave\n\nOedeme extensif allant jusqu'au tronc\net/ou\nSymptomes systémiques persistant (hypotension < 80mmHg PAS, avec signes de choc, saignements incontrolables, défaillance multiviscerale, réaction anaphylactoide)\n\nANTIVENIN VIPERFAV = 2 ampoules de 2mg dans 100-125ml sur 1H.\nRenouvellable à H4 si évolution défavorable\nSURVEILLANCE REANIMATOIRE"}]}, {"id": "syndrome-scorpionique", "name": "Syndrome scorpionique", "header": "Evenimation : syndrome scorpionique", "images": [], "sections": [{"h": null, "body": "En France, la piqure est extremement douloureuse, mais le venin n'est pas dangereux.\n\nSur les autres continents, le venin des scorpions est pauvre en enzymes, ce qui rend la réaction locale très atténuée, voire absente.\nLa toxicité est alors neurologique et cardiologique par action sur les canaux ioniques membranaires.\n\nAucune des espèces françaises n'est mortelle.\nEN FRANCE METROPOLITAINE, IL N'A ETE SIGNALE AUCUNE ENVENIMATION DEPASSANT LE GRADE 1\nCe qui n'est pas le cas à l'etranger, où certaines envenimation scorpioniques sont mortelles.\n\nIl existe des sérums, spécifiques de chaque espèce, et non délivrés systématiquement.\nL’efficacité du sérum décroît en effet si l’injection est faite dans un délai supérieur à une heure après la piqûre du scorpion. Après 24h, le risque mortel n'existe plus. A noter aussi, que le venin est plus dangereux en période séche.\n\nPour les espèces en dehors de la France, la toxicité sera essentiellement cardiotoxique, (bien que certaines espèces aient un venin neurotoxique). Il faudra alors mettre en place une surveillance hospitalière/réanimatoire scopée, ainsi qu'un protecteur cardiaque"}, {"h": "Grade 0", "body": "Piqure sans envenimation.\nMarque du dard, pas d 'oedeme ou de reaction locale.\n\nDESINFECTION + SURVEILLANCE"}, {"h": "Grade 1", "body": "Envenimation minime.\nOedeme local, pas de signes généraux\n\nDESINFECTION + TRAITEMENT SYMPTOMATIQUE + SURVEILLANCE"}, {"h": "Grade 2", "body": "Envenimation modérée\nOedème régional, symptômes systémiques modérés (Sueurs, frissons, tremblements, sialorrhée, rhinorrhée, poussée tensionnelle, vomissements)\n\nPas de mise en jeu du pronostic vital\nSURVEILLANCE HOSPITALIERE AFIN DE PREVENIR UNE EVOLUTION VERS LE GRADE 3"}, {"h": "Grade 3", "body": "Envenimation grave\nOedeme extensif.\nSymptomes systémiques persistants avec signes de choc, défaillance cardiaque et/ou neurologique, avec tableau d'ischémie myocardique et de coma\n\nSERUM SPECIFIQUE + PROTECTEUR CARDIAQUE + MESURES DE REA\nSURVEILLANCE REANIMATOIRE"}]}, {"id": "atraxisme", "name": "Atraxisme", "header": "Evenimation : atraxisme", "images": [], "sections": [{"h": null, "body": "Les mygalomorphes de la famille des hexathélidés (genre Atrax) sont, à juste titre, considérées comme les araignées les plus dangereuses du monde.\n\nElles vivent uniquement sur la côte est de l’Australie et de Tasmanie où elles sont appelées “Funnel-web spiders”\nCes araignées de grande taille (corps de 6 cm, chélicères de 5 mm) se caractérisent par leur importante agressivité, tout particulièrement chez le mâle en période de reproduction qui attaque volontiers les humains.\n\nLes “Funnel-web spiders” produisent un venin neurotoxique redoutable pour les humains et les primates à cause de la présence d’atracotoxines (famille de neurotoxines présynaptiques telles la robustoxine d’A.robustus ou la versutoxine d’H.versuta). Ces toxines induisent dans un premier temps une libération massive des neurotransmetteurs au niveau du système nerveux autonome et des jonctions neuromusculaires à l’origine d’un “orage catécholaminergique”. Dans un second temps, ces mêmes toxines ralentissent l’inactivation des canaux sodiques, entraînant un blocage de la transmission nerveuse"}, {"h": "CLINIQUE", "body": "L’atraxisme est caractérisé par une évolution biphasique. La phase aiguë se développe quelques minutes après la morsure. La douleur locale est intense et syncopale, accompagnée de pilo-érection, hypersudation et fasciculations loco-régionales.\nCes dernières se généralisent rapidement (visage, langue, muscles intercostaux), pouvant entraîner des spasmes musculaires et un risque de suffocation si les masséters et le larynx sont atteints\n\nD’autres signes généraux peuvent être observés lors de la phase aiguë : tachycardie, hypertension artérielle, troubles du rythme cardiaque, nausées, vomissements, hypersalivation, anisocorie, larmoiement, angoisse, confusion, œdème cérébral, coma\nÀ ce stade, des décès ont été observés et attribués à des œdèmes aigus pulmonaires lésionnels. Après une amélioration apparente des symptômes, la seconde phase se caractérise par l’apparition progressive d’une hypotension réfractaire et d’apnées suivies d’un arrêt cardio-respiratoire.\nDes coagulations intravasculaires disséminées et une acidose métabolique liée à une rhabdomyolyse ont été observées."}, {"h": "PARACLINIQUE", "body": "Le diagnostic est uniquement clinique."}, {"h": "TRAITEMENT", "body": "Les Australiens ont mis au point un protocole thérapeutique qui a permis non seulement de réduire à zéro la mortalité, mais aussi de nettement diminuer la morbidité de l’atraxisme\nCe protocole est fondé sur la mise en place préhospitalière d’un bandage compressif (ralentissant la diffusion du venin tout en respectant la vascularisation du membre mordu) associé à une attelle d’immobilisation.\nÀ l’hôpital, où l’antivenin spéciﬁque doit être disponible, ce dispositif est levé sous surveillance médicale. L’antidote est injecté par voie intraveineuse lente en cas d’apparition du moindre symptôme général d’envenimation.\nLa neutralisation des atracotoxines est rapide, permettant une disparition des signes cliniques en quelques minutes.\nDes traitements symptomatiques (soins locaux, antalgiques, vessie de glace, amines pressives, benzodiazépine,etc.) complètent si besoin ce protocole thérapeutique"}]}, {"id": "latrodectisme", "name": "Latrodectisme", "header": "Evenimation : latrodectisme", "images": [], "sections": [{"h": null, "body": "Concerne les veuves noires d'Amérique.\n\nLe latrodectisme est un aranéisme neurotoxique.\nLe venin est neurotoxique, à cause de l'alpha-latrotoxine (ou α-latroxine),\nL’α-LTx se tétramérise dans la bicouche lipidique de la membrane présynaptique,formant des néo-canaux qui laissent entrer le calcium dans la cellule. Cette entrée calcique brutale entraîne une exocytose massive des neurotransmetteurs (acétylcholine, adrénaline, dopamine) à l’origine de la symptomatologie"}, {"h": "CLINIQUE", "body": "La piqure est habituellement peu douloureuse.\nLes principaux symptômes sont, dans les minutes qui suivent, des myalgies diffuses avec rigidité musculaire notamment du tronc et du visage (faciès latrodectismica pathognomonique avec trismus, œdème facial, chéilite, blépharo-conjonctivite, rhinorrhée)\n\nIl peut exister des troubles neurovégétatifs (hyperthermie en pic avec phases d’hypothermie, hypersudation généralisée, alternance de bradycardie et tachycardie), des céphalées, des spasmes musculaires (contraction des muscles thoraciques, abdominaux et faciaux), des paresthésies (en particulier une paresthésie de la plante des pieds, pathognomonique) des troubles psychiques (état d’anxiété intense, crainte de mourir, et hallucinations), des nausées, un érythème et un œdème local.\n\nLes cas mortels sont très rares ; les personnes les plus sensibles sont les enfants en bas âge, les personnes âgées, ou ayant des problèmes cardiaques.\nOn ne comptabilise en moyenne qu'un décès pour 200 cas de morsures.\nL'atteinte cardiaque, sous forme de myocardite, est rare et mortelle"}, {"h": "PARACLINIQUE", "body": "Le diagnostic est uniquement clinique.\nLes anomalies biologiques les plus fréquentes sont une hyperleucocytose et une élévation de la créatine kinas"}, {"h": "TRAITEMENT", "body": "Un traitement symptomatique, antalgique, doit être administré.\nL'utilisation de benzodiazépines permet de lutter contre les contractures musculaires. (Dantrium possible)\n\nLe gluconate de calcium en perfusion intraveineuse lente (250 mL en 1 heure, renouvelable 12 heures plus tard) est utilisé aﬁn d’améliorer les composantes algiques et neurovégétatives\n\nLe sérum anti venimeux n'est plus utilisé en France"}]}, {"id": "loxocelisme", "name": "Loxocelisme", "header": "Evenimation : loxoscelisme", "images": ["loxo_clin_1.webp", "loxo_clin_2.webp", "loxo_clin_3.webp", "loxo_clin_4.webp", "loxo_clin_5.webp", "loxo_clin_6.webp"], "sections": [{"h": null, "body": "Le loxoscelisme est un aranéisme nécrosant, potentiellement retardé.\n\nLe venin des loxosceles possède une activité nécrosante cytotoxique qui serait principalement due à une “nécrotoxine” appelée sphingomyélinase D7.\nCelle-ci serait à l’origine d’une inﬂammation locale avec activation de médiateurs responsables de la destruction tissulaire.\nD’autres enzymes présentes en grandes quantités dans ce venin potentialisent probablement l’action de la sphingomyélinase D :phosphatases alcalines, hyaluronidases, lipases, métalloprotéases, sérines-protéases...\n\nCertains ont évoqué l’intervention possible de Clostridium perfringens qui,ayant contaminé les chélicères de l’araignée,s’associerait à l’action de la sphingomyélinase D en favorisant l’anoxie tissulaire propice au développement des phénomènes de nécrose"}, {"h": "CLINIQUE", "body": "Les troubles peuvent se limiter à une réaction inflammatoire locale, peu douloureuse voire meme indolore, guérissant spontanément, parfois après petite escarre et ulcération minime.\nToutefois, dans sa forme majeure, le loxocelisme se caractérise par une nécrose plus ou moins étendue apparaissant en quelques heures voire d'un état de choc.\nLa lésion alors un aspect caractéristique :triade “rouge - blanc - bleue”, avec un halo érythémateux entourant une zone ischémique claire centrée par une nécrose bleutée.\nUn décollement cutané nécrotique se développe ensuite avec formation d’une escarre creusante centrifuge de profondeur variable,pouvant atteindre les loges musculaires.\nLa cicatrisation de mauvaise qualité est lente, pouvant nécessiter plusieurs semaines voire plusieurs mois d’évolution entachée de phases de récidives et de surinfections.\nDes signes généraux peuvent être observés lors de loxoscélisme cutané : asthénie intense dans un contexte de syndrome grippal (ﬁèvre, céphalées, douleurs diffuses)\n\n**Un avis de chirurgie plastique peut être demandé, car une exérèse très large des parties nécrosées peut être nécessaire.**\n\nPlus rarement, dans les 2 à 3 jours après la morsure, un état de choc peut survenir avec hémolyse, hémoglobinurie, ictère, fièvre, insuffisance rénale et troubles de la conscience.\n\nCe syndrome très rare est imprévisible, il semble n'être en fonction ni de l'âge du sujet, ni du site de la morsure, ni de l'importance des premiers symptômes"}, {"h": "PARACLINIQUE", "body": "Le diagnostic est uniquement clinique."}, {"h": "TRAITEMENT", "body": "Un traitement symptomatique, antalgique, doit être administré.\nIl n'existe pas de traitement spécifique, le traitement sera celui des complications."}], "gallery_caption": "Photos de 4 patients différents, mordus en été par des loxocèles, à Toulon (Var). 3 d'entre eux ont nécessité une prise en charge chirurgicale assez délabrante."}, {"id": "steatodisme", "name": "Steatodisme", "header": "Evenimation : steatodisme", "images": [], "sections": [{"h": null, "body": "Le venin a une structure similaire à celui du genre \"Latrodectus\", et est neurotoxique, a cause de l'alpha-latrotoxine (ou α-latroxine), qui agit en détruisant les vésicules synaptiques.\n\nUne recrudescence de steatodisme a été observée par le CAP de Marseille."}, {"h": "CLINIQUE", "body": "Le steatodisme est en fait un tableau de latrodectisme a minima, spontanement résolutif d'après les données actuelles de la littérature.\nIl doit être évoqué devant un tableau de latrodectisme atténué.\n\nLe traitement proposé est symptomatique, avec antalgie et AINS.\nLa sruveillance hospitalière n'est actuellement pas recommandée."}, {"h": "PARACLINIQUE", "body": "Le diagnostic est uniquement clinique."}, {"h": "TRAITEMENT", "body": "Un traitement symptomatique, antalgique, doit être administré.\nL'utilisation de benzodiazépines permet de lutter contre les contractures musculaires.\n\nL'utilisation de calcium ou de magnésium n'a pas fait la preuve de son efficacité.\n\nLe sérum anti venimeux, bien qu'assez largement utilisé, n'a pas démontré son efficacité."}]}, {"id": "araneisme-necosant", "name": "Araneisme nécrosant", "header": "Evenimation : araneïsme nécrosant", "images": [], "sections": [{"h": null, "body": "C'est un syndrome regroupant les envenimations par de nombreuses espèces d’araignées dont le venin n’entraîne pratiquement que des signes loco-régionaux est cité dans la littérature sous le terme “d’aranéisme nécrosant”.\nPour de tels aranéismes, les symptômes sont probablement liés à d’autres facteurs, telle la présence d’enzymes dans le venin ou une éventuelle surinfection bactérienne"}, {"h": "CLINIQUE", "body": "Signes loco-regionaux, avec oedème plus ou moins compressifs.\n\nLe principal risque est à la sur-infection."}, {"h": "PARACLINIQUE", "body": "Le diagnostic est uniquement clinique."}, {"h": "TRAITEMENT", "body": "Le traitement des “aranéismes nécrosants” reste uniquement symptomatique, une attention particulière devant être apportée aux soins locaux et à la prévention de toute surinfection."}]}, {"id": "syndrome-hymenoptere", "name": "Syndrome hymenoptere", "header": "Evenimation : hyménoptères", "images": [], "sections": [{"h": null, "body": "La structure du venin est assez semblable au sein de l'ordre des hymenoptères.\nIl est composé d'amines biogènes, de substances histaminolibératrices et de divers enzymes.\nLa toxicité n'est pas directe, elle est liée au pouvoir allergisant extremement élevé du venin\n\nA noter, le venin est thermolabile."}, {"h": "Abeille", "body": "L'abeille a un dard barbelé qui reste fiché dans la peau après la piqure, qu'il conviendra de retirer.\nLa suite du traitement est symptomatique.\n\n2 cas particuliers :\n- Allergie et réaction anaphylactique : le traitement est alors celui de la réaction anaphylactique, en fonction de sa gravité\n- Choc toxinique, dans le cas de multiples piqures (peu fréquent en France). Dans le cas, on retrouvera un choc anaphylactoïde, dont le traitement est aspécifique du venin."}, {"h": "Bourdon", "body": "Le bourdon, beaucoup moins aggressif que l'abeille, dispose lui aussi d'un dard barbelé.\nLa réaction locale est en général moins forte que l'abeille.\nLa prise en charge est la même que pour l'abeille."}, {"h": "Guèpe & polistes", "body": "La guèpe a un dard lisse qui ne reste pas fiché dans la peau après la piqure, ce qui permet à la guèpe de piquer plusieurs fois.\nLa reaction locale est plus intense que celle de l'abeille, et sera volontiers accompagnée d'un prurit persistant.\nLa suite du traitement est symptomatique.\n\n2 cas particuliers :\n- Allergie et réaction anaphylactique : le traitement est alors celui de la réaction anaphylactique, en fonction de sa gravité\n- Choc toxinique, dans le cas de multiples piqures (peu fréquent en France). Dans le cas, on retrouvera un choc anaphylactoïde, dont le traitement est aspécifique du venin."}, {"h": "Frelon", "body": "Comme la guèpe, le frelon a un dard lisse qui ne reste pas fiché dans la peau après la piqure, ce qui lui permet de piquer plusieurs fois.\nLa réaction locale est plus intense que celle de la guèpe, avec une vive douleur, et sera volontiers accompagnée d'un oedeme local\nLa suite du traitement est symptomatique.\n\n2 cas particuliers :\n- Allergie et réaction anaphylactique : le traitement est alors celui de la réaction anaphylactique, en fonction de sa gravité\n- Choc toxinique, dans le cas de multiples piqures (peu fréquent en France). Dans le cas, on retrouvera un choc anaphylactoïde, dont le traitement est aspécifique du venin."}]}, {"id": "tetrodotoxisme", "name": "Tétrodotoxisme", "header": "Tétrodotoxisme", "images": [], "sections": [{"h": null, "body": "Le tétrodotoxisme est l'intoxication par la tétrodotoxine (TTX), l'un des poisons les plus puissants du monde aquatique (actif à des concentrations de l'ordre du nanomolaire), contre lequel il n'existe pas d'antidote.\n\nLa toxine n'est pas produite par le poisson lui-même : elle provient de bactéries associées à certaines algues rouges (genre Jania, Rhodophyta) et s'accumule le long de la chaîne alimentaire. Le foie, les gonades, les intestins et la peau en sont les plus riches ; le poisson y est lui-même résistant, son canal sodique différant de celui de l'homme.\n\nEn France, le tétrodotoxisme est longtemps resté cantonné aux territoires d'outre-mer (Guyane, Réunion, Nouvelle-Calédonie, Polynésie), après consommation de poissons de l'ordre des Tétraodontiformes. La colonisation de la Méditerranée par le poisson-lièvre (Lagocephalus sceleratus) et la possible contamination des coquillages européens font désormais craindre l'émergence de ce risque en France métropolitaine.\nSource : thèse du Dr Pierrick Gouel, « Caractéristiques cliniques et prise en charge thérapeutique des intoxications par tétrodotoxine en France », Faculté de médecine des Antilles et de la Guyane, 2021."}, {"h": "MÉCANISME", "body": "Comme c'est le cas pour la saxitoxine, les tétrodotoxines inhibent l'activité des canaux sodiques durant la phase ascendante du potentiel d'action\nLa tétrodotoxine bloque de manière très sélective le pore des canaux sodium voltage-dépendants, empêchant ainsi le passage de l'influx nerveux. Ce blocage sous un certain niveau est réversible.\n\nLa DL50 serait de 20 mg pour un être humain ou plus généralement on constate une DL minimale 8–20 μg·kg-1 ; in vitro le blocage apparaît pour une concentration de 0,1 μg·ml-1.\nIl n'existe pas d'antidote connu.\n\nLes poissons y sont insensibles car leur canal est différent de celui des hommes. Pour bloquer un influx nerveux la tétrodotoxine serait 2 500 fois plus puissante que la procaïne."}, {"h": "CLINIQUE", "body": "Le tableau clinique se présente ainsi :\n\n- atteinte du système nerveux avec paresthésies orales et périorales, nausées souvent accompagnées de vomissements, parfois avec diarrhées et douleurs abdominales ;\n- vertiges, pâleur, sensation de malaise, puis ataxie et engourdissement général avec la sensation de flotter. Fourmillements et picotements des extrémités précédant la paralysie des membres inférieurs et des extrémités ;\n- modifications de la sensibilité profonde, la gorge et le larynx sont touchés très tôt ce qui provoque une dysphagie voire une aphagie complète, ainsi qu’une dysphonie ;\n- dilatation des pupilles (mydriase) ;\n- dans le cas d’intoxication aigüe, bradycardie et hypotension, hypersalivation, hypothermie, hypersudation, asthénie ;\n- cyanose des extrémités et des lèvres, hémorragies pétéchiales sur le corps.\n\nLe décès est souvent dû à une paralysie respiratoire, l’état de conscience n’étant en général pas affecté.\n\nOn peut distinguer quatre stades dans l’intoxication :\n- paresthésies buccales suivies dans certains cas de nausées et vomissements.\n- paralysie motrice des doigts et des membres (les réflexes ostéotendineux restent présents).\n- perte des mouvements musculaires volontaires, cyanose, hypotension, dysphagie et dysphonie.\n- détresse respiratoire, puis arrêt."}, {"h": "PRISE EN CHARGE", "body": "Il n'existe pas d'antidote. La prise en charge est symptomatique et réanimatoire : surveillance et assistance ventilatoire (le décès survient par paralysie respiratoire, la conscience restant souvent préservée), décontamination digestive si l'ingestion est récente.\nToute suspicion impose un contact avec le centre antipoison et une surveillance hospitalière. La mortalité rapportée reste élevée (environ 10 % dans la série française, jusqu'à 23 % en Italie)."}]}], "intro": {"header": "Venomed", "sections": [{"h": null, "body": "Ce projet est une initiative personnelle lancée en septembre 2016, pendant mon second semestre de médecine générale aux Hopitaux de Marseille.\n\nLe contenu de l'application a été soumis à la relecture par le Dr De Haro, du centre anti-poison de Marseille.\n\nVenomed est à l’usage des soignants, pour compiler les prises en charges des envenimations les plus courantes en France métropolitaine.\nL'application essaye d'apporter, outre les données scientifiques, une galerie d'images pour permettre au practicien de reconnaitre l'animal incriminé si besoin.\n\nA noter que Venomed ne traite QUE de la faune sauvage en France metropolitaine.\nUne piqure/morsure par un animal importé necessitera un appel au centre anti-poison, et selon le cas, une consultation en urgence dans un centre de soins et une prise en charge différente\n\nDonnées animales et picturales :\nLe site https://serpent.cheloniophilie.com,\ndont sont tirées toutes les photos de\nserpents, avec l'aimable autorisation\nde son webmaster\nToutes les autres images utilisées dans cette application sont disponibles par simple recherche sur Google ou sur Word ; je n'en détiens pas les droits. Cette appli est libre de droits.\n\nSi vous avez aimé cette appli, vous pouvez aussi télécharger gratuitement Mediglotte, l'application pour l'examen clinique d'urgence dans 40 langues !\n\nPierre-Alexis BALAZ"}]}, "sources": {"header": "Venomed", "sections": [{"h": null, "body": "SOURCES & REMERCIEMENTS\n\nLe site de référence mondial : https://www.vapaguide.info/\n\nDONNÉES MÉDICALES & ARTICLES\nAvec l'aide du Dr De Haro du CAP Marseille.\n\n- « Envenimation cobraïque » (Georges Mion, Sébastien Larréché, Mohammed Chani, Alain Benois)\n- « Envenimations et morsures animales » (J-J. Morand)\n- « Morsures d'araignées : les aranéismes d'importance médicale » (Philip Pommier, Christine Rollard, Luc de Haro)\n- « Animaux venimeux terrestres » (L. de Haro)\n- « Management of snakebites in France » (Luc de Haro)\n- « Un cas de stéatodisme observé en Languedoc après morsure d'araignée du genre Steatoda » (Philip Pommier, Christine Rollard, Luc de Haro)\n- Collège National des Enseignants de Réanimation Médicale (CNERM)\n\nDONNÉES ANIMALES ET PICTURALES\n- Le site https://serpent.cheloniophilie.com, dont sont tirées toutes les photos de serpents, avec l'aimable autorisation de son webmaster.\n- Wikipedia, pour les photos hors celles des serpents, et pour les données relatives au mode de vie des animaux présentés.\n\nPHOTOGRAPHIES CLINIQUES\nClichés de loxocélisme, de morsure de vipère (envenimation grade 2) et de morsure de couleuvre réalisés par l'auteur, à l'HIA Sainte-Anne (Toulon) et au CH de Hyères, avec l'accord des patients concernés."}]}, "galleries": [{"id": "morsures-serpents", "title": "Photos de morsures", "category": "menu-serpents", "items": [{"img": "couleuvre_bite.webp", "caption": "Morsure de couleuvre d'Esculape, près de Tours. Les traces de dents, en forme de demi-cercle, sont bien visibles. Il n'y a pas de traces de crochets car la majorité des couleuvres n'en disposent pas."}, {"img": "viper_bite_1.webp", "caption": "Morsure de vipère, sous-espèce non précisée, à Hyères. On remarque les 2 points correspondant à la trace des crochets et au point d'injection. On note le net œdème du pied atteint, et l'on devine une suffusion hémorragique sous la malléole. La biologie confirmait les troubles de la coagulation, signant ainsi un grade 2."}, {"img": "viper_bite_2.webp", "caption": "Morsure de vipère, sous-espèce non précisée, à Hyères. On remarque les 2 points correspondant à la trace des crochets et au point d'injection. On note le net œdème du pied atteint, et l'on devine une suffusion hémorragique sous la malléole. La biologie confirmait les troubles de la coagulation, signant ainsi un grade 2."}]}]};